def is_sum_free(s):
    """Checks if a set s is sum-free: for all x, y in s, x + y is not in s."""
    s_list = list(s)
    n = len(s_list)
    for i in range(n):
        for j in range(n):
            # Check x + y = z, where x, y, z are in s.
            # If x+y is in s, the set is NOT sum-free.
            sum_val = s_list[i] + s_list[j]
            if sum_val in s:
                return False
    return True

