def is_sum_free(A):
    """Checks if a set A is sum-free: for all x, y, z in A, x + y != z."""
    # Since we check against a specific condition x+y=z, we iterate over all triplets.
    # If A is a singleton {a}, the only choice is x=a, y=a, z=a.
    # The condition becomes 2a = a, which means a = 0.
    # Since the domain is {1, ..., 40}, this is impossible.

    # For a general check (though unnecessary for the singletons):
    elements = list(A)
    for x in elements:
        for y in elements:
            s = x + y
            if s in A:
                return False
    return True

